from collections import defaultdict

def max_repeating_substring_length(N, S):
    # Dictionary to store the frequency of each substring
    substring_count = defaultdict(int)

    # Sliding window approach to count all substrings
    for i in range(N):
        for j in range(i + 1, N + 1):
            substring = S[i:j]
            substring_count[substring] += 1

    # Find the maximum length of a substring that appears at least twice
    max_length = 0
    for length, count in substring_count.items():
        if count >= 2:
            max_length = max(max_length, len(length))

    return max_length

