    # Iterate over possible lengths of substrings
    for length in range(1, N + 1):
        # Use a set to store substrings of the current length
        seen_substrings = set()

        # Iterate over the string with a sliding window of the current length
        for i in range(N - length + 1):
            substring = S[i:i + length]

            # Check if the substring has already been seen in the current window
            if substring in seen_substrings:
                # Update the maximum length if the current length is greater
                max_length = max(max_length, length)
            else:
                # Add the substring to the set
                seen_substrings.add(substring)

    return max_length

