import heapq

def can_win(N, M, S):
    # Create a graph representation
    graph = [[] for _ in range(N + 1)]
    for i in range(N):
        if S[i] == 0:
            for j in range(1, M + 1):
                if i + j <= N:
                    graph[i].append((i + j, j))

    # Priority queue for BFS
    pq = [(0, 0, [])]  # (current distance, current position, current sequence)

    while pq:
        dist, pos, seq = heapq.heappop(pq)

        # If we reach Square N, return the sequence
        if pos == N:
            return seq

        # Explore all possible moves
        for next_pos, num in graph[pos]:
            if next_pos not in seq:
                heapq.heappush(pq, (dist + 1, next_pos, seq + [num]))

    # If no path is found, return -1
    return -1

