def solve(n, m, s):
    # Convert string S to a list of integers
    game_over_squares = [int(char) for char in s]

    # Initialize DP array
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    # Fill the DP array
    for i in range(1, n + 1):
        for x in range(1, m + 1):
            if i + x <= n and not game_over_squares[i + x]:
                dp[i + x] = min(dp[i + x], dp[i] + 1)

    # If it's impossible to reach Square N, return -1
    if dp[n] == float('inf'):
        return -1

    # Backtrack to find the sequence
    sequence = []
    current = n
    while current > 0:
        for x in range(1, m + 1):
            if current + x <= n and not game_over_squares[current + x] and dp[current + x] == dp[current] - 1:
                sequence.append(x)
                current += x
                break

    # Reverse the sequence to get the correct order
    sequence.reverse()

    # Print the sequence
    print(' '.join(map(str, sequence)))

