import heapq

def bfs(graph, start, end):
    queue = [(0, [start])]
    visited = set([start])

    while queue:
        current_distance, path = heapq.heappop(queue)

        if path[-1] == end:
            return path

        for neighbor in graph[path[-1]]:
            if neighbor not in visited:
                visited.add(neighbor)
                heapq.heappush(queue, (current_distance + 1, path + [neighbor]))

    return None

