def count_permutations(n, k):
    MOD = 10**9 + 7

    # If k is out of bounds, return 0
    if k > n * (n + 1) // 2 or k < 0:
        return 0

    # Initialize DP table
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    # Base case: there's one permutation of length 0 with oddness 0
    dp[0][0] = 1

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(k + 1):
            # If we place i at position j, the remaining elements must have oddness j - (i - 1)
            if j >= i - 1:
                dp[i][j] = (dp[i][j] + dp[i - 1][j - (i - 1)]) % MOD

    return dp[n][k]

