from itertools import permutations

def count_permutations_with_oddness(n, k):
    MOD = 10**9 + 7
    count = 0

    # Generate all permutations of the set {1, 2, ..., n}
    for perm in permutations(range(1, n + 1)):
        # Calculate the oddness of the permutation
        oddness = sum(abs(i - perm[i - 1]) for i in range(1, n + 1))

        # Check if the oddness is equal to k
        if oddness == k:
            count += 1

    # Return the count modulo 10^9 + 7
    return count % MOD

