def count_permutations(n, k):
    MOD = 10**9 + 7

    # Initialize dp array
    dp = [[0] * (2 * n + 1) for _ in range(n + 1)]

    # Base case: there's one permutation of length 0 with oddness 0
    dp[0][0] = 1

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(2 * n + 1):
            if j - i >= 0:
                dp[i][j] = (dp[i][j] + dp[i - 1][j - i]) % MOD
            if j + i <= 2 * n:
                dp[i][j] = (dp[i][j] + dp[i - 1][j + i]) % MOD

    # The result is the number of permutations of length n with oddness k
    return dp[n][k]

