    # Base case
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(k + 1):
            for pos in range(1, i + 1):
                if j - abs(i - pos) >= 0:
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - abs(i - pos)]) % MOD

    return dp[n][k]

