MOD = 10**9 + 7

@lru_cache(None)
def count_permutations(n, k, pos, last):
    if pos == n:
        return 1 if k == 0 else 0
    count = 0
    for i in range(1, n + 1):
        if i != last and abs(i - pos) == k:
            count = (count + count_permutations(n, k - abs(i - pos), pos + 1, i)) % MOD
    return count

