def count_permutations(n, k):
    MOD = 10**9 + 7

    # If k is greater than n^2, return 0
    if k > n * n:
        return 0

    # If k is 0, return 1 if n is even, otherwise 0
    if k == 0:
        return 1 if n % 2 == 0 else 0

    # Initialize the dp table
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(k + 1):
            if j >= 2:
                dp[i][j] = (dp[i][j] + dp[i - 1][j - 2]) % MOD
            if j > 0:
                dp[i][j] = (dp[i][j] + dp[i - 1][j]) % MOD

    return dp[n][k]

