def is_valid(A, B, N):
    # Check if the condition C_i = B_i - A_i - 1 holds for all persons
    for i in range(1, N + 1):
        if A[i] == -1 or B[i] == -1:
            continue
        C_i = B[i] - A[i] - 1
        if C_i != 0:
