    return True

def backtrack(A, B, N, floor, persons_on_elevator):
    # Base case: if all persons have been processed
    if floor == 2 * N:
        return is_valid(A, B, N)

    # Try placing the current person on the elevator
    A[floor] = floor
    B[floor] = floor + 1
    if backtrack(A, B, N, floor + 1, persons_on_elevator + 1):
        return True

    # Try placing the current person off the elevator
    A[floor] = -1
    B[floor] = -1
    if backtrack(A, B, N, floor + 1, persons_on_elevator):
        return True

    # Try placing the current person on a different floor
    for i in range(1, 2 * N + 1):
        if i not in A and i not in B:
            A[floor] = i
            B[floor] = i + 1
            if backtrack(A, B, N, floor + 1, persons_on_elevator + 1):
                return True
            A[floor] = -1
            B[floor] = -1

    return False

