def is_valid(A, B, N):
    occupied = set()
    for i in range(1, N + 1):
        if A[i - 1] != -1:
            occupied.add(A[i - 1])
        if B[i - 1] != -1:
            occupied.remove(B[i - 1])
        if len(occupied) > 1:
            return False
    return True

def backtrack(A, B, N, index):
    if index == N:
        return is_valid(A, B, N)

    for i in range(1, 2 * N + 1):
        if i not in occupied:
            A[index] = i
            if backtrack(A, B, N, index + 1):
                return True
            A[index] = -1

    return False

