def count_ways(N, M, K):
    MOD = 998244353
    dp = [[0] * (K + 1) for _ in range(N + 1)]

    # Base cases
    dp[0][0] = 1
    dp[1][0] = M

    # Fill the DP table
    for i in range(2, N + 1):
        for j in range(K + 1):
            # Paint the i-th block with a new color
            if j + 1 <= K:
                dp[i][j + 1] = (dp[i][j + 1] + dp[i - 1][j]) % MOD
            # Paint the i-th block with the same color as the (i-1)-th block
            dp[i][j] = (dp[i][j] + dp[i - 1][j]) % MOD

    # Sum up all valid ways to paint N blocks with at most K adjacent blocks painted in the same color
    result = sum(dp[N][j] for j in range(K + 1)) % MOD
    return result

