import heapq

def dijkstra(graph, start):
    # Initialize distances to infinity
    distances = {vertex: float('inf') for vertex in graph}
    distances[start] = 0

    # Priority queue to store (distance, vertex)
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current_vertex = heapq.heappop(priority_queue)

        # If the current distance is greater than the stored distance, skip this vertex
        if current_distance > distances[current_vertex]:
            continue

        # Explore neighbors
        for neighbor, weight in graph[current_vertex]:
            distance = current_distance + weight

            # If a shorter path is found, update the distance and add to the priority queue
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return distances

def count_non_shortest_path_edges(graph, n):
    # Find the shortest paths from each vertex
    shortest_paths = {}
    for vertex in range(1, n + 1):
        shortest_paths[vertex] = dijkstra(graph, vertex)

    # Count non-shortest path edges
    non_shortest_path_edges = 0
    for vertex in range(1, n + 1):
        for neighbor, weight in graph[vertex]:
            if shortest_paths[vertex][neighbor] != weight:
                non_shortest_path_edges += 1

    return non_shortest_path_edges

