def find_longest_path(graph, start):
    visited = set()
    stack = [(start, 0)]
    max_depth = 0

    while stack:
        node, depth = stack.pop()
        if node not in visited:
            visited.add(node)
            max_depth = max(max_depth, depth)
            for neighbor in graph[node]:
                stack.append((neighbor, depth + 1))

    return max_depth

