            for k in range(j + 1, n):
                # Calculate the circumcenter of the triangle formed by points i, j, k
                circumcenter_point = circumcenter(points[i], points[j], points[k])
                # Calculate the radius of the circle
                radius = distance(circumcenter_point, points[i])
                # Update the minimum radius
                min_radius = min(min_radius, radius)

    return min_radius

