import math

def distance(p1, p2):
    return math.sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

def welzl(points, border, k):
    if k == 0:
        return (None, float('inf'))
    if k == 1:
        return (points[0], 0)
    if k == 2:
        p1, p2 = points[:2]
        center = ((p1[0] + p2[0]) / 2, (p1[1] + p2[1]) / 2)
        radius = distance(center, p1)
        return (center, radius)

    # Choose a random point from the border
    i = k
    while i < k + len(border) and border[i] in points:
        i += 1
    if i == k + len(border):
        i = k

    # Recursively find the SEC for the remaining points
    center, radius = welzl(points, border[:i] + border[i+1:], k-1)

    # Check if the chosen point is inside the current SEC
    if distance(center, points[i]) <= radius:
        return (center, radius)

    # Add the chosen point to the border and find the SEC again
    return welzl(points, border + [points[i]], k)

def min_enclosing_circle(points):
    if len(points) < 3:
        return (points[0], 0)

    # Sort points by x-coordinate
    points.sort(key=lambda p: p[0])

    # Use Welzl's algorithm to find the SEC
    center, radius = welzl(points, [], len(points))

    return radius

