def welzl(points, hull, r, k):
    if k == 0:
        return hull, r
    if k == 1:
        return [points[0]], distance(points[0], points[1])
    if k == 2:
        return [points[0], points[1], points[2]], distance(points[0], points[1])

    p = points[k]
    hull, r = welzl(points, hull, r, k - 1)

    if distance(p, hull[-1]) <= r:
        return hull, r
    if distance(p, hull[-2]) <= r:
        return hull[:-1] + [p], r

    q = hull[-1]
    if distance(p, q) <= r:
        return hull[:-2] + [p, q], r

    for i in range(k):
        if distance(p, hull[i]) <= r:
            hull = hull[:i] + [p] + hull[i:]
            break

    return welzl(hull, hull, r, k - 1)

