    if n == 3:
        x1, y1 = points[0]
        x2, y2 = points[1]
        x3, y3 = points[2]
        return distance(x1, y1, x2, y2) / 2

    # Find the convex hull of the points
    hull = []
    for point in points:
        while len(hull) >= 2 and orientation(hull[-2], hull[-1], point) <= 0:
            hull.pop()
        hull.append(point)

    # Calculate the radius of the circle passing through the first three points of the hull
