class SegmentTree:
    def __init__(self, n):
        self.n = n
        self.tree = [None] * (4 * n)
        self.lazy = [None] * (4 * n)

    def build(self, arr, node, start, end):
        if start == end:
            self.tree[node] = SortedList([arr[start]])
            return
        mid = (start + end) // 2
        self.build(arr, 2 * node, start, mid)
        self.build(arr, 2 * node + 1, mid + 1, end)
        self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1]

    def update(self, node, start, end, index, value):
        if start == end:
            self.tree[node].remove(self.tree[node][0])
            self.tree[node].add(value)
            return
        mid = (start + end) // 2
        if index <= mid:
            self.update(2 * node, start, mid, index, value)
        else:
            self.update(2 * node + 1, mid + 1, end, index, value)
        self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1]

    def query(self, node, start, end, left, right):
        if left > end or right < start:
            return SortedList()
        if left <= start and end <= right:
            return self.tree[node]
        mid = (start + end) // 2
        left_half = self.query(2 * node, start, mid, left, right)
        right_half = self.query(2 * node + 1, mid + 1, end, left, right)
        return left_half + right_half

