def can_assign_positions(N, M, constraints):
    # Build the graph
    graph = defaultdict(list)
    for L, R, D in constraints:
        graph[L].append((R, D))

    # Check for cycles using DFS
    visited = [False] * (N + 1)
    in_stack = [False] * (N + 1)

    def has_cycle(node):
        if visited[node]:
            return False
        if in_stack[node]:
            return True
        visited[node] = True
        in_stack[node] = True
        for neighbor, _ in graph[node]:
            if has_cycle(neighbor):
                return True
        in_stack[node] = False
        return False

    if has_cycle(1):
        return "No"

    # Topological sort
    indegree = [0] * (N + 1)
    for node in range(1, N + 1):
        for neighbor, _ in graph[node]:
            indegree[neighbor] += 1

    queue = deque([node for node in range(1, N + 1) if indegree[node] == 0])
    positions = [0] * (N + 1)

    while queue:
        node = queue.popleft()
        positions[node] = max(positions[node], positions[node - 1] + 1)
        for neighbor, D in graph[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    # Check if all positions are consistent
    for L, R, D in constraints:
        if positions[R] - positions[L] != D:
            return "No"

    return "Yes"

