    while queue:
        x, y, magic_uses = queue.popleft()

        if (x, y) == end:
            return magic_uses

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny, H, W) and grid[nx][ny] == '.' and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, magic_uses))

        # Check if the current position is within the 5x5 area centered at (x, y)
        if (x - 2 <= start[0] <= x + 2) and (y - 2 <= start[1] <= y + 2):
            queue.append((x, y, magic_uses + 1))

    return -1

