def dfs(node, parent, graph, dp, mod):
    if dp[node] != -1:
        return dp[node]

    # Initialize the number of ways for the current node
    dp[node] = 1

    # Iterate over the children of the current node
    for child in graph[node]:
        if child != parent:
            # Recursively calculate the number of ways for the child
            child_ways = dfs(child, node, graph, dp, mod)
            # Combine the ways for the current node and its children
            dp[node] = (dp[node] * child_ways) % mod

    return dp[node]

