def dfs(node: int, parent: int, adj_list: defaultdict, dp: List[List[int]], mod: int) -> int:
    # Initialize the dp array for the current node
    dp[node][0] = 1  # Base case: one way to assign number 1 to the current node
    dp[node][1] = 0  # No way to assign number 2 to the current node yet

    for neighbor in adj_list[node]:
        if neighbor != parent:
