def count_eulerian_paths(n: int, edges: List[List[int]]) -> List[int]:
    # Build the graph
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    # Count the in-degree and out-degree of each vertex
    in_degree = [0] * (n + 1)
    out_degree = [0] * (n + 1)
    for u in range(1, n + 1):
        for v in graph[u]:
            out_degree[u] += 1
            in_degree[v] += 1

    # Find the number of Eulerian paths starting from each vertex
    eulerian_paths = [0] * (n + 1)
    for k in range(1, n + 1):
        if in_degree[k] == out_degree[k]:
            # If the in-degree and out-degree are equal, there is exactly one Eulerian path
            eulerian_paths[k] = 1
        elif in_degree[k] == out_degree[k] + 1:
            # If the in-degree is one more than the out-degree, there are no Eulerian paths
            eulerian_paths[k] = 0
        elif out_degree[k] == in_degree[k] + 1:
            # If the out-degree is one more than the in-degree, there are no Eulerian paths
            eulerian_paths[k] = 0
        else:
            # If the in-degree and out-degree differ by more than one, there are no Eulerian paths
            eulerian_paths[k] = 0

    return eulerian_paths

