    if A < 0 or B < 0 or C < 0:
        return "No"

    # Try to make each choice
    for choice in choices:
        if choice == "AB":
            if A > 0 and B > 0:
                A -= 1
                B -= 1
            elif A > 0:
                A -= 1
            elif B > 0:
                B -= 1
            else:
                return "No"
        elif choice == "AC":
            if A > 0 and C > 0:
                A -= 1
                C -= 1
            elif A > 0:
                A -= 1
            elif C > 0:
                C -= 1
            else:
                return "No"
        elif choice == "BC":
            if B > 0 and C > 0:
                B -= 1
                C -= 1
            elif B > 0:
                B -= 1
            elif C > 0:
                C -= 1
            else:
                return "No"

    # If all choices are made successfully
    return "Yes"

