def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        parent[rootX] = rootY

def count_connected_cities(N, roads, railways):
    # Initialize parent arrays for both graphs
    parent_roads = list(range(N + 1))
    parent_railways = list(range(N + 1))

    # Union roads
    for p, q in roads:
        union(parent_roads, p, q)

    # Union railways
    for r, s in railways:
        union(parent_railways, r, s)

    # Count connected cities by both roads and railways
    result = []
    for i in range(1, N + 1):
        if find(parent_roads, i) == find(parent_railways, i):
            result.append(1)
        else:
            result.append(0)

    return result

