def build_tree(N, edges):
    parent = [0] * (N + 1)
    depth = [0] * (N + 1)
    for u, v in edges:
        parent[v] = u
    return parent, depth

def calculate_depth(N, parent, depth):
    for i in range(1, N + 1):
        if depth[i] == 0:
            depth[i] = 1
            current = i
            while parent[current] != 0:
                depth[parent[current]] = depth[current] + 1
                current = parent[current]

def count_connected_components(N, parent, depth, L, R):
    max_depth = 0
    for i in range(L, R + 1):
        max_depth = max(max_depth, depth[i])
    count = 0
    for i in range(L, R + 1):
        if depth[i] == max_depth:
            count += 1
    return count

