def bfs(graph, start, end, L):
    queue = deque([(start, 0, 0)])  # (node, distance, fuel)
    visited = set()
    visited.add(start)

    while queue:
        node, distance, fuel = queue.popleft()

        if node == end:
            return distance // L + (1 if distance % L != 0 else 0)

        for neighbor, weight in graph[node].items():
            if neighbor not in visited:
                visited.add(neighbor)
                new_fuel = fuel + weight
                if new_fuel <= L:
                    queue.append((neighbor, distance + weight, new_fuel))
                else:
                    # If traveling halfway, check if the remaining distance can be covered with the remaining fuel
                    remaining_distance = weight - (L - fuel)
                    if remaining_distance > 0:
                        new_fuel = L
                        queue.append((neighbor, distance + remaining_distance, new_fuel))

    return -1

