def floyd_warshall(graph):
    n = len(graph)
    dist = [[float('inf')] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for u, v, w in graph:
        dist[u-1][v-1] = w
        dist[v-1][u-1] = w
    for k in range(n):
        for i in range(n):
            for j in range(n):
                dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])
    return dist

def min_fueling_times(n, m, l, roads, queries):
    graph = defaultdict(list)
    for u, v, w in roads:
        graph[u-1].append((v-1, w))
        graph[v-1].append((u-1, w))

    dist = floyd_warshall(graph)

    dp = [[float('inf')] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 0

    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] + dist[k][j] <= l:
                    dp[i][j] = 0
                else:
                    dp[i][j] = 1

    results = []
    for s, t in queries:
        if dp[s-1][t-1] == float('inf'):
            results.append(-1)
        else:
            results.append(dp[s-1][t-1])

    return results

