from collections import defaultdict, deque

def bfs(graph, start, end, L):
    n = len(graph)
    visited = [False] * n
    parent = [-1] * n
    queue = deque([(start, 0, 0)])  # (node, distance, fuel)

    while queue:
        node, distance, fuel = queue.popleft()

        if node == end:
            return distance, fuel

        if visited[node]:
            continue

        visited[node] = True

        for neighbor, cost in graph[node]:
            new_fuel = fuel + cost
            if new_fuel <= L:
                queue.append((neighbor, distance + 1, new_fuel))
                parent[neighbor] = node

    return -1, -1

def min_fullings(graph, start, end, L):
    distance, fuel = bfs(graph, start, end, L)
    if distance == -1:
        return -1

    fullings = 0
    current_node = end
    while current_node != start:
        if fuel < L:
            fullings += 1
            fuel = L
        current_node = parent[current_node]

    return fullings

