def max_item_sum(R, C, K, items):
    # Create a graph representation of the grid
    graph = defaultdict(list)
    for r, c, v in items:
        graph[(r, c)].append((r + 1, c))
        graph[(r, c)].append((r, c + 1))

    # Initialize DP table
    dp = defaultdict(lambda: defaultdict(lambda: defaultdict(lambda: defaultdict(int))))

    # Base case: starting from (1, 1) with 0 items picked up in both rows
    dp[1][1][0][0] = items[0][2]

    # Fill the DP table
    for i in range(1, R + 1):
        for j in range(1, C + 1):
            for k in range(4):
                for m in range(4):
                    if i == 1 and j == 1 and k == 0 and m == 0:
                        continue

                    # Calculate the maximum sum from the previous state
                    max_sum = 0
                    if i > 1:
                        max_sum = max(max_sum, dp[i - 1][j][k][m])
                    if j > 1:
                        max_sum = max(max_sum, dp[i][j - 1][k][m])

                    # Update the DP table
                    if k < 3:
                        dp[i][j][k + 1][m] = max(dp[i][j][k + 1][m], max_sum + items[i - 1][j - 1][2])
                    if m < 3:
                        dp[i][j][k][m + 1] = max(dp[i][j][k][m + 1], max_sum + items[i - 1][j - 1][2])

    # Find the maximum sum from the state (R, C, 0, 0)
    max_sum = 0
    for k in range(4):
        for m in range(4):
            max_sum = max(max_sum, dp[R][C][k][m])

    return max_sum

