def solve(n, s):
    if n < 3:
        return -1

    # Count the number of 'o's and 'x's
    o_count = s.count('o')
    x_count = s.count('x')

    # If the counts are not equal, it's impossible to satisfy all answers
    if o_count != x_count:
        return -1

    # Initialize the first animal
    if s[0] == 'o':
        species = 'S'
    else:
        species = 'W'

    # Assign species to the rest of the animals
    for i in range(1, n):
        if s[i] == 'o':
            if species == 'S':
                species = 'W'
            else:
                species = 'S'
        else:
            if species == 'S':
                species = 'S'
            else:
                species = 'W'

    return species * n

