    n = len(s)
    for i in range(n):
        if s[i] == 'o':
            if assignment[i] != assignment[(i - 1) % n] or assignment[i] != assignment[(i + 1) % n]:
                return False
        elif s[i] == 'x':
            if assignment[i] == assignment[(i - 1) % n] or assignment[i] == assignment[(i + 1) % n]:
                return False
    return True

