def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def count_similar_numbers(l, r):
    """Count numbers in the range [l, r] that are similar to 2017."""
    count = 0
    for x in range(l, r + 1, 2):  # Iterate over odd numbers only
        if is_prime(x) and is_prime((x + 1) // 2):
            count += 1
    return count

