def max_illuminated_squares(H, W, grid):
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # Up, Down, Left, Right
    max_illuminated = 0

    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                continue  # Skip obstacles

            # Initialize BFS queue with the starting square
            queue = deque([(i, j)])
            visited = set([(i, j)])
            illuminated = 1  # Start with the current square

            while queue:
                x, y = queue.popleft()

                for dx, dy in directions:
                    nx, ny = x + dx, y + dy

                    # Check if the new position is within bounds and not visited
                    if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] == '.' and (nx, ny) not in visited:
                        visited.add((nx, ny))
                        queue.append((nx, ny))
                        illuminated += 1

            max_illuminated = max(max_illuminated, illuminated)

    return max_illuminated

