def can_sort_by_operations(N, P):
    # Check if the permutation is already sorted
    if P == sorted(P):
        return -1

    # Check if the permutation can be sorted by adjacent swaps
    # We need to check if there are any cycles in the permutation
    # If there are cycles, it means the permutation cannot be sorted
    visited = [False] * N
    for i in range(N):
        if not visited[i]:
            cycle_size = 0
            j = i
            while not visited[j]:
                visited[j] = True
                j = P[j] - 1
                cycle_size += 1
            if cycle_size > 1:
                return -1

    # If no cycles are found, the permutation can be sorted
    return N - 1

