def find_cycles(P):
    n = len(P)
    visited = [False] * n
    cycles = []

    def dfs(node, path):
        visited[node] = True
        path.append(node)
        next_node = P[node] - 1
        if not visited[next_node]:
            dfs(next_node, path)
        else:
            if path[0] in path:
                cycles.append(path)

    for i in range(n):
        if not visited[i]:
            dfs(i, [])

    return cycles

def sort_permutation(P):
    cycles = find_cycles(P)
    if any(len(cycle) > 2 for cycle in cycles):
        return -1

    operations = []
    for cycle in cycles:
        n = len(cycle)
        for i in range(n - 1):
            operations.append(cycle[i] + 1)

    return operations

