def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        parent[rootX] = rootY

def kruskal(graph):
    edges = sorted(graph.items(), key=lambda item: item[1])
    parent = {i: i for i in range(1, len(graph) + 1)}
    mst = []
    mst_weight = 0

    for edge in edges:
        u, v, weight = edge
        if find(parent, u) != find(parent, v):
            union(parent, u, v)
            mst.append((u, v, weight))
            mst_weight += weight

    return mst

