        tree[node] = (arr[start], start)
        return
    mid = (start + end) // 2
    build_segment_tree(arr, tree, start, mid, 2 * node + 1)
    build_segment_tree(arr, tree, mid + 1, end, 2 * node + 2)
    left_min, left_x = tree[2 * node + 1]
    right_min, right_x = tree[2 * node + 2]
    if left_min < right_min:
        tree[node] = (left_min, left_x)
    else:
        tree[node] = (right_min, right_x)

def update_segment_tree(tree, start, end, node, index, value):
    if start == end:
        tree[node] = (value, index)
        return
    mid = (start + end) // 2
    if index <= mid:
        update_segment_tree(tree, start, mid, 2 * node + 1, index, value)
    else:
        update_segment_tree(tree, mid + 1, end, 2 * node + 2, index, value)
    left_min, left_x = tree[2 * node + 1]
    right_min, right_x = tree[2 * node + 2]
    if left_min < right_min:
        tree[node] = (left_min, left_x)
    else:
        tree[node] = (right_min, right_x)

