def is_valid_matrix(matrix, S, T, U, V):
    N = len(matrix)

    # Check rows
    for i in range(N):
        if S[i] == 0:
            if matrix[i].count(0) != U[i]:
                return False
        else:
            if matrix[i].count(1) != U[i]:
                return False

    # Check columns
    for j in range(N):
        col = [matrix[i][j] for i in range(N)]
        if T[j] == 0:
            if col.count(0) != V[j]:
                return False
        else:
            if col.count(1) != V[j]:
                return False

    return True

def backtrack(matrix, S, T, U, V, row, col):
    N = len(matrix)

    # If we have filled the entire matrix, check if it is valid
    if row == N:
        return is_valid_matrix(matrix, S, T, U, V)

    # Try setting the current element to 0
    matrix[row][col] = 0
    if backtrack(matrix, S, T, U, V, row, col + 1):
        return True

    # Try setting the current element to 1
    matrix[row][col] = 1
    if backtrack(matrix, S, T, U, V, row, col + 1):
        return True

    # Backtrack
    matrix[row][col] = 0
    return False

