def is_unbalanced(s):
    n = len(s)
    if n < 2:
        return False

    # Iterate over all possible substrings
    for i in range(n):
        for j in range(i + 1, n + 1):
            substring = s[i:j]
            char_count = {}

            # Count the frequency of each character in the substring
            for char in substring:
                if char in char_count:
                    char_count[char] += 1
                else:
                    char_count[char] = 1

            # Check if more than half of the characters are the same
            half_length = j - i
            if max(char_count.values()) > half_length / 2:
                return True

    return False

def find_unbalanced_substring(s):
    n = len(s)
    for i in range(n):
        for j in range(i + 1, n + 1):
            if is_unbalanced(s[i:j]):
                return i, j
    return -1, -1

